//! What `egret init` tells the operator about the bootstrap admin's password
//! (KI-146).
//!
//! A password the operator supplied in `EGRET_ADMIN_PASSWORD` is never
//! printed: they already have it, and stdout is what lands in terminal
//! scroll-back and CI logs. A generated one is printed once, because nobody
//! has it yet.

/// The bootstrap admin's password and where it came from.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum AdminPassword {
    /// Read from `EGRET_ADMIN_PASSWORD`.
    Supplied(String),
    /// Generated by `egret init`.
    Generated(String),
}

impl AdminPassword {
    /// The supplied value, or `generate()` when the variable is unset or empty
    /// (an empty password is never what an operator meant).
    pub fn from_env(var: Option<String>, generate: impl FnOnce() -> String) -> Self {
        match var {
            Some(v) if !v.is_empty() => Self::Supplied(v),
            _ => Self::Generated(generate()),
        }
    }

    /// The password itself, for hashing.
    pub fn secret(&self) -> &str {
        match self {
            Self::Supplied(p) | Self::Generated(p) => p,
        }
    }
}

/// The lines `egret init` prints for the admin it created.
pub fn admin_report(email: &str, password: &AdminPassword) -> String {
    match password {
        AdminPassword::Supplied(_) => format!(
            "Bootstrap admin: {email}\nPassword: taken from EGRET_ADMIN_PASSWORD (not shown)"
        ),
        AdminPassword::Generated(p) => format!(
            "Bootstrap admin: {email}\nPassword: {p}\n(generated; shown only this once)"
        ),
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn a_supplied_password_is_never_printed() {
        let pw = AdminPassword::from_env(Some("S3cret-from-env".into()), || unreachable!());
        assert_eq!(pw.secret(), "S3cret-from-env");
        let out = admin_report("a@x", &pw);
        assert!(!out.contains("S3cret-from-env"), "{out}");
        assert!(out.contains("taken from EGRET_ADMIN_PASSWORD"), "{out}");
    }

    #[test]
    fn a_generated_password_is_printed_once() {
        let pw = AdminPassword::from_env(None, || "gen-123".into());
        assert_eq!(pw, AdminPassword::Generated("gen-123".into()));
        assert_eq!(admin_report("a@x", &pw).matches("gen-123").count(), 1);
    }

    #[test]
    fn an_empty_variable_generates_rather_than_setting_an_empty_password() {
        let pw = AdminPassword::from_env(Some(String::new()), || "gen-456".into());
        assert_eq!(pw, AdminPassword::Generated("gen-456".into()));
    }
}
